using KennelPro.Interfaces.Reproduction; using KennelPro.Models.Enums; using KennelPro.Models.Reproduction; using KennelPro.Services.Dogs; using KennelPro.Validators;
namespace KennelPro.Services.Reproduction;
public class MatingService { readonly IMatingRepository _repo; readonly DogService _dogs; public MatingService(IMatingRepository repo,DogService dogs){_repo=repo;_dogs=dogs;} public async Task<List<Mating>> GetForCurrentKennelAsync(){var k=await _dogs.GetCurrentKennelIdAsync();return k==null?new():(await _repo.GetByKennelIdAsync(k.Value)).ToList();} public async Task<Mating?> GetByIdAsync(Guid id){var x=await _repo.GetByIdAsync(id); if(x==null)return null; return await _dogs.GetDogForCurrentKennelAsync(x.FemaleDogId)!=null&&await _dogs.GetDogForCurrentKennelAsync(x.MaleDogId)!=null?x:null;} async Task<(bool,string)> Check(Mating x){var f=await _dogs.GetDogForCurrentKennelAsync(x.FemaleDogId);var m=await _dogs.GetDogForCurrentKennelAsync(x.MaleDogId);if(f==null||m==null)return(false,"Parents must belong to your kennel.");if(f.Gender!=Gender.Female||m.Gender!=Gender.Male)return(false,"Select a female and a male dog.");return MatingValidator.Validate(x,out var e)?(true,""):(false,e);} public async Task<(bool,string)> AddAsync(Mating x){var c=await Check(x);if(!c.Item1)return c;x.Id=x.Id==Guid.Empty?Guid.NewGuid():x.Id;await _repo.AddAsync(x);return(true,"");} public async Task<(bool,string)> UpdateAsync(Mating x){var old=await GetByIdAsync(x.Id);if(old==null)return(false,"Mating not found.");var c=await Check(x);if(!c.Item1)return c;await _repo.UpdateAsync(x);return(true,"");} public async Task<bool> DeleteAsync(Guid id){if(await GetByIdAsync(id)==null)return false;await _repo.DeleteAsync(id);return true;} }
